steps.input:
matches=[]
for f in root.rglob('*.jsonl'):
    txt=f.read_text(errors='ignore')
    if 'task-a68ecb5b' in txt: matches.append((str(f), txt.count('task-a68ecb5b')))
print(matches)

import json
for fn,_ in matches:
    print('\n===',Path(fn).name,'===')
    for line in Path(fn).read_text().splitlines():
        try: ob=json.loads(line)
        except: continue
        if ob.get('type')=='message':
            msg=ob.get('message',{})
            role=msg.get('role')
            cont=msg.get('content')
            if role=='user':
                txt=''.join(c.get('text','') for c in cont if c.get('type')=='text') if isinstance(cont,list) else str(cont)
                if 'task-a68ecb5b' in txt: print('USER:',txt[:2000].replace('\n',' '))
            elif role=='assistant':
                txt=''.join(c.get('text','') for c in cont if c.get('type')=='text') if isinstance(cont,list) else str(cont)
                if txt: print('ASSISTANT:',txt[:500].replace('\n',' '))

